local module = {}
local Interval = require(script.Interval)
local Timeout = require(script.Timeout)

-- 创建并立即启动一个间隔计时器
-- @param func 要执行的函数
-- @param dt 间隔时间（秒）
-- @param inst 是否立即执行第一次
-- @return Interval对象
function module:SetInterval(func, dt, inst)
    local interval = Interval.new(func, dt, inst)
    interval:Start()
    
    return interval
end

-- 创建一个间隔计时器，但不立即启动
-- @param func 要执行的函数
-- @param dt 间隔时间（秒）
-- @param inst 是否立即执行第一次
-- @return Interval对象
function module:CreateInterval(func, dt, inst)
    local interval = Interval.new(func, dt, inst)
    return interval
end

-- 创建并立即启动一个超时计时器
-- @param func 要执行的函数
-- @param delay 延迟时间（秒）
-- @return Timeout对象
function module:SetTimeout(func, delay)
    local timeout = Timeout.new(func, delay)
    timeout:Start()
    return timeout
end

-- 创建一个超时计时器，但不立即启动
-- @param func 要执行的函数
-- @param delay 延迟时间（秒）
-- @return Timeout对象
function module:CreateTimeout(func, delay)
    local timeout = Timeout.new(func, delay)
    return timeout
end

-- 停止一个间隔计时器
-- @param interval 要停止的Interval对象
function module:ClearInterval(interval)
    interval:Stop()
end

-- 停止一个超时计时器
-- @param timeout 要停止的Timeout对象
function module:ClearTimeout(timeout)
    timeout:Stop()
end

return module